/* Creates an administrator and delivers the requested credential handoff email.
 *
 *   node scripts/provisionAdmin.mjs --email admin@example.org --first-name Ada --last-name Lovelace --department Tech
 *
 * The temporary password is prompted for without echoing it. It is deliberately
 * sent once in the onboarding email because this is the explicitly requested
 * handoff workflow; it is never logged, stored in the database as plaintext, or
 * returned by this script. The recovery link is generated by Supabase but emailed
 * by the configured Gmail SMTP account, so this command is the required companion
 * to account creation -- SQL alone cannot send SMTP mail.
 */

import { createHash, randomBytes } from 'node:crypto';
import { createRequire } from 'node:module';
import { stdin, stdout } from 'node:process';
import { env } from './lib/env.mjs';

const require = createRequire(import.meta.url);
const nodemailer = require('nodemailer');

function arg(flag) {
  const index = process.argv.indexOf(flag);
  return index === -1 ? '' : String(process.argv[index + 1] || '').trim();
}

function fail(message) { console.error(message); process.exit(1); }
function clean(value) { return String(value || '').trim(); }
function hash(value) { return createHash('sha256').update(value).digest('hex'); }

async function hiddenPrompt(label) {
  if (!stdin.isTTY) fail('Pass --password only from a secure terminal, or run this command interactively to enter the password without echoing it.');
  return new Promise((resolve) => {
    let value = '';
    stdout.write(label);
    stdin.setRawMode(true); stdin.resume(); stdin.setEncoding('utf8');
    const onData = (chunk) => {
      for (const char of chunk) {
        if (char === '\r' || char === '\n') {
          stdin.off('data', onData); stdin.setRawMode(false); stdin.pause(); stdout.write('\n'); resolve(value); return;
        }
        if (char === '\u0003') { stdin.off('data', onData); stdin.setRawMode(false); stdin.pause(); stdout.write('\n'); process.exit(130); }
        if (char === '\u007f' || char === '\b') { value = value.slice(0, -1); }
        else if (char >= ' ') value += char;
      }
    };
    stdin.on('data', onData);
  });
}

const email = clean(arg('--email')).toLowerCase();
const firstName = clean(arg('--first-name'));
const lastName = clean(arg('--last-name'));
const department = clean(arg('--department')) || 'MSI Camps';
const origin = clean(arg('--origin')) || 'https://camp-grids.vercel.app';
const allowedDomains = clean(arg('--allowed-domains'))
  .split(',').map((value) => value.trim().toLowerCase()).filter(Boolean);
let password = arg('--password');

if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) fail('Pass --email <administrator email>.');
if (!firstName || !lastName) fail('Pass both --first-name and --last-name.');
if (!password) {
  password = await hiddenPrompt('Temporary password (not shown): ');
  const confirmation = await hiddenPrompt('Repeat temporary password: ');
  if (password !== confirmation) fail('The temporary passwords did not match. Nothing was created.');
}
if (password.length < 12 || password.length > 72 || !/[a-z]/i.test(password) || !/[0-9]/.test(password)) {
  fail('The temporary password must be 12-72 characters and contain at least one letter and one digit.');
}

let redirectTo;
try {
  redirectTo = new URL('admin-onboarding.html', origin.endsWith('/') ? origin : `${origin}/`);
} catch { fail('--origin must be an absolute URL, for example https://camp-grids.vercel.app'); }
const nonce = randomBytes(32).toString('base64url');
redirectTo.searchParams.set('onboarding', nonce);

const supabaseUrl = await env('SUPABASE_URL');
const serviceRole = await env('SUPABASE_SERVICE_ROLE_KEY');
const smtpHost = await env('GMAIL_SMTP_HOST');
const smtpUser = await env('GMAIL_SMTP_USER');
const smtpPassword = await env('GMAIL_SMTP_APP_PASSWORD');
const smtpFrom = await env('GMAIL_SMTP_FROM') || smtpUser;
const smtpFromName = await env('GMAIL_SMTP_FROM_NAME') || 'MSI CampGrids';
const smtpPort = Number(await env('GMAIL_SMTP_PORT') || 465);
if (!supabaseUrl || !serviceRole) fail('SUPABASE_URL and SUPABASE_SERVICE_ROLE_KEY must be set in .env.');
if (!smtpHost || !smtpUser || !smtpPassword || !smtpFrom) fail('GMAIL_SMTP_HOST, GMAIL_SMTP_USER, GMAIL_SMTP_APP_PASSWORD, and GMAIL_SMTP_FROM must be set in .env.');

const api = async (path, init = {}) => {
  const response = await fetch(`${supabaseUrl.replace(/\/$/, '')}${path}`, {
    ...init,
    headers: { apikey: serviceRole, Authorization: `Bearer ${serviceRole}`, 'Content-Type': 'application/json', ...(init.headers || {}) },
  });
  if (!response.ok) {
    let message = `${response.status} ${response.statusText}`;
    try { const payload = await response.json(); message = payload.message || payload.msg || payload.error || message; } catch { /* keep status */ }
    throw new Error(message);
  }
  /* REST updates requested with return=minimal legitimately answer 204 with no
     body. Treat that as success instead of throwing "Unexpected end of JSON" after
     the account has already been created. */
  const text = await response.text();
  if (!text) return null;
  try { return JSON.parse(text); } catch { throw new Error('Supabase returned an unreadable response.'); }
};

try {
  // The database function owns password policy, role assignment, token-column
  // integrity, audit logging, and session invalidation. This script never writes
  // directly to auth.users.
  await api('/rest/v1/rpc/create_admin_account', {
    method: 'POST',
    body: JSON.stringify({
      p_email: email, p_first_name: firstName, p_last_name: lastName,
      p_password: password, p_department: department,
      ...(allowedDomains.length ? { p_allowed_domains: allowedDomains } : {}),
    }),
  });

  const profiles = await api(`/rest/v1/profiles?select=id&email=eq.${encodeURIComponent(email)}&limit=1`);
  const userId = profiles?.[0]?.id;
  if (!userId) throw new Error('The administrator was created but its profile could not be read for email onboarding.');

  const link = await api('/auth/v1/admin/generate_link', {
    method: 'POST',
    body: JSON.stringify({ type: 'recovery', email, options: { redirectTo: redirectTo.href } }),
  });
  const actionLink = link?.action_link;
  if (!actionLink || typeof actionLink !== 'string') throw new Error('Supabase did not generate the one-time administrator link.');

  const now = new Date().toISOString();
  await api(`/rest/v1/admin_onboarding_tokens?user_id=eq.${userId}&used_at=is.null`, {
    method: 'PATCH', body: JSON.stringify({ used_at: now }),
  });
  await api('/rest/v1/admin_onboarding_tokens', {
    method: 'POST',
    headers: { Prefer: 'return=minimal' },
    body: JSON.stringify({ user_id: userId, token_hash: hash(nonce), expires_at: new Date(Date.now() + 30 * 60 * 1000).toISOString() }),
  });

  const transport = nodemailer.createTransport({
    host: smtpHost, port: smtpPort, secure: smtpPort === 465,
    auth: { user: smtpUser, pass: smtpPassword.replace(/\s+/g, '') },
  });
  const subject = 'Your MSI CampGrids administrator access';
  const text = [
    `Hello ${firstName},`, '',
    'You have been given MSI CampGrids administrator access.', '',
    `Sign-in email: ${email}`,
    `Temporary password: ${password}`, '',
    'Open this one-time link within 30 minutes to verify your mailbox and choose a private password:',
    actionLink, '',
    'The link can be used once. After setting your password, sign in at:',
    `${origin.replace(/\/$/, '')}/admin/`, '',
    'If you were not expecting this access, do not use the password or link; contact MSI IT immediately.',
  ].join('\n');
  const html = `<p>Hello ${firstName.replace(/[&<>"']/g, '')},</p><p>You have been given <strong>MSI CampGrids administrator access</strong>.</p><p><strong>Sign-in email:</strong> ${email}<br><strong>Temporary password:</strong> ${password.replace(/[&<>"']/g, '')}</p><p>Open this one-time link within 30 minutes to verify your mailbox and choose a private password:</p><p><a href="${actionLink}">Set up my administrator access</a></p><p>The link can be used once. After setting your password, sign in at <a href="${origin.replace(/\/$/, '')}/admin/">${origin.replace(/\/$/, '')}/admin/</a>.</p><p>If you were not expecting this access, do not use the password or link; contact MSI IT immediately.</p>`;
  const info = await transport.sendMail({ from: `"${smtpFromName}" <${smtpFrom}>`, to: email, subject, text, html });
  if (info.rejected?.length) throw new Error(`Gmail rejected delivery to ${info.rejected.join(', ')}.`);

  await api(`/rest/v1/profiles?id=eq.${userId}`, { method: 'PATCH', body: JSON.stringify({ password_invite_sent_at: now }) });
  console.log(`Administrator provisioned and onboarding email accepted by Gmail for ${email}.`);
  console.log('The temporary password and one-time link were not printed.');
} catch (error) {
  console.error(`Administrator provisioning failed: ${error.message}`);
  console.error('If the account was created before this failure, correct the reported issue and re-run this command with a new temporary password.');
  process.exit(1);
}
